import{_ as t,o as a,c as d,a3 as o}from"./chunks/framework.DeRSg1wr.js";const h=JSON.parse('{"title":"日志框架适配器方式","description":"选择 MDC 或 TLog 日志适配器，区分业务异步与异步 appender。","frontmatter":{"title":"日志框架适配器方式","date":"2022-09-12T13:44:06.000Z","permalink":"/pages/5223de/","description":"选择 MDC 或 TLog 日志适配器，区分业务异步与异步 appender。"},"headers":[],"relativePath":"pages/5223de/index.md","filePath":"10.文档/070.日志框架适配方式/010.日志框架适配器方式.md"}'),r={name:"pages/5223de/index.md"};function c(p,e,n,l,i,s){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="日志框架适配器方式" tabindex="-1">日志框架适配器方式 <a class="header-anchor" href="#日志框架适配器方式" aria-label="Permalink to &quot;日志框架适配器方式&quot;">​</a></h1><p>TLog 2.0 通过日志配置文件输出标签。框架入口先建立 TLog 上下文，再由日志 pattern、encoder、layout 或 converter 把标签写入日志。</p><table tabindex="0"><thead><tr><th>日志实现</th><th>完整标签放在指定位置</th><th>在消息前追加标签</th></tr></thead><tbody><tr><td>logback</td><td>普通 encoder + <code>%X{tl}</code></td><td><code>AspectLogbackEncoder</code> 或 <code>AspectLogbackLayout</code></td></tr><tr><td>Log4j2</td><td><code>%X{tl}</code>；旧 <code>%TX{tl}</code> 别名保留</td><td>TLog 插件 <code>%tmsg</code></td></tr><tr><td>旧 Log4j</td><td><code>%X{tl}</code>，SLF4J 绑定到对应实现</td><td><code>AspectLog4jPatternLayout</code></td></tr></tbody></table><p>配置入口：<a href="/pages/f62a84/">logback</a>、<a href="/pages/8d5538/">Log4j2</a>、<a href="/pages/a48c8e/">旧 Log4j</a>、<a href="/pages/ddebe2/">MDC</a>。</p><h2 id="选择一种标签输出方式" tabindex="-1">选择一种标签输出方式 <a class="header-anchor" href="#选择一种标签输出方式" aria-label="Permalink to &quot;选择一种标签输出方式&quot;">​</a></h2><p>新接入可以先用 MDC <code>%X{tl}</code>，并设置 <code>tlog.mdc-enable=true</code>。已有 TLog encoder/layout/converter 的项目可保留配置，但应避免它和 <code>%X{tl}</code> 同时输出重复标签。</p><p>标签只会在已有 TLog 上下文的日志中出现。启动日志、未接入的后台线程或没有适配器的调用不会因为替换 encoder 就自动形成一条业务链路。</p><h2 id="两种异步分别处理" tabindex="-1">两种异步分别处理 <a class="header-anchor" href="#两种异步分别处理" aria-label="Permalink to &quot;两种异步分别处理&quot;">​</a></h2><p>业务异步指 <code>@Async</code>、线程池、CompletableFuture 等业务代码换线程，需要在提交和执行之间传播上下文。日志异步指 appender 把日志事件交给另一个线程，需要在事件入队前保留标签或 MDC。</p><p>MDC 输出可使用日志框架的事件快照；使用消息前缀适配器时，按框架页面选择 TLog 异步 appender。只安装日志异步 appender，不会自动装饰业务线程池；只包装业务线程池，也不能修复在日志消费线程临时读取上下文的错误 layout。</p><p>纯 Java 应用仍需提供日志实现与对应 SLF4J binding。实际验证范围见<a href="/guide/compatibility/">兼容性</a>。</p>',11)])])}const g=t(r,[["render",c]]);export{h as __pageData,g as default};
